"""NMR-specific processing functions for FoodomicsPy.This module contains functions for aligning NMR spectra usinga reference peak."""import numpy as npimport pandas as pd# =============================================================================# REFERENCE-PEAK ALIGNMENT# =============================================================================def align_reference_peak(    df,    window=(-0.3, 0.3),    target_ppm=0.0,    fill_value=0.0,):    """    Align NMR spectra using a reference peak.    For each spectrum, the maximum signal within the selected ppm    window is shifted to the target ppm position. Alignment is    performed using integer-point shifting.    Parameters    ----------    df : pandas.DataFrame        NMR spectral data with samples in rows and ppm values        in columns.    window : tuple of float, default=(-0.3, 0.3)        Ppm region containing the reference peak. The order of the        two values does not matter.    target_ppm : float, default=0.0        Ppm position to which the detected reference peak is aligned.    fill_value : float, default=0.0        Value used to fill empty positions created at the edges of        shifted spectra.    Returns    -------    pandas.DataFrame        Aligned NMR spectra with the original index and columns        preserved.    Raises    ------    ValueError        If no ppm values are found within the selected reference        window.    Notes    -----    This function uses integer-point shifting. It does not interpolate    between spectral points.    Signal values shifted beyond the spectral boundaries are discarded.    Empty positions created at the opposite edge are filled with    `fill_value`.    Examples    --------    Align spectra using a reference peak around 0 ppm:    >>> import pandas as pd    >>> import foodomicspy as f    >>> df = pd.DataFrame(    ...     [    ...         [0.0, 0.2, 1.0, 0.3, 0.0],    ...         [0.0, 0.1, 0.4, 1.1, 0.2],    ...     ],    ...     index=["sample_1", "sample_2"],    ...     columns=[0.2, 0.1, 0.0, -0.1, -0.2],    ... )    >>> df_aligned = f.nmr.align_reference_peak(    ...     df,    ...     window=(-0.2, 0.2),    ...     target_ppm=0.0,    ... )    Use `NaN` to fill empty edge positions:    >>> import numpy as np    >>> df_aligned = f.nmr.align_reference_peak(    ...     df,    ...     window=(-0.2, 0.2),    ...     target_ppm=0.0,    ...     fill_value=np.nan,    ... )    """    ppm = df.columns.astype(float).to_numpy()    X = df.to_numpy(dtype=float)    # Select the reference-peak region    low_ppm, high_ppm = sorted(window)    mask = (ppm >= low_ppm) & (ppm <= high_ppm)    if not mask.any():        raise ValueError(            f"No ppm values found inside the window {window}."        )    # Find the column nearest to the target ppm    target_index = np.argmin(        np.abs(ppm - target_ppm)    )    # Find the maximum peak within the window for each spectrum    window_indices = np.where(mask)[0]    peak_indices = window_indices[        np.argmax(X[:, mask], axis=1)    ]    # Calculate the required integer-point shifts    shifts = target_index - peak_indices    # Create the output array    X_aligned = np.full(        X.shape,        fill_value,        dtype=float,    )    n_points = X.shape[1]    # Shift without wrapping values to the opposite edge    for row, shift in enumerate(shifts):        shift = int(shift)        if shift == 0:            X_aligned[row] = X[row]        elif shift > 0:            X_aligned[row, shift:] = X[                row,                :n_points - shift,            ]        else:            shift = abs(shift)            X_aligned[row, :n_points - shift] = X[                row,                shift:,            ]    return pd.DataFrame(        X_aligned,        index=df.index,        columns=df.columns,    )